// v23.xx (gfx18), HIS ORDER (2026-10-12) on the graphics program, item 6: HIT PAUSE, drawn only. The frame a pillager or a
// machine takes a hit (its hit flash, hitT, rises), its pose freezes for 60 ms (times EFFECT INTENSITY: half at HALF, none at
// OFF): a pillager's stride, facing and walk, a machine's every animated part (entT replaces the raid clock in the machine
// painters). The hit jolt still plays over it. Never you, never a teammate (their bodies are not on this path), never in
// the sim (nothing draws there), and nothing here is written onto the body: the state lives in a WeakMap on the drawing side,
// so every number a fight reads is exactly as before. A linked window freezes on the mirrored hit flash too.
var HITP=(typeof WeakMap==='function')?new WeakMap():null;
function hitPauseOf(o,ph,face,mv){
  var s, h, t, k;
  if(!HITP||!o||typeof o!=='object'||typeof G==='undefined'||!G||G.sim) return null;
  k=(CFG.fxInt===undefined||CFG.fxInt===null)?1:+CFG.fxInt; if(!(k>=0)) k=1;
  h=+o.hitT||0; t=G.t||0; s=HITP.get(o);
  if(!s){ s={last:h,until:-1,tf:t,ph:ph,face:face,mv:mv,on:false}; HITP.set(o,s); return s; }
  if(h>s.last+0.005&&k>0){ s.until=t+0.06*Math.min(1,k); s.tf=t; s.ph=ph; s.face=face; s.mv=mv; }
  s.last=h; s.on=(t<s.until);
  return s;
}
function entT(e){ var s=hitPauseOf(e,0,0,false); return (s&&s.on)?s.tf:((typeof G!=='undefined'&&G)?(G.t||0):0); }
